698	bool CachedReadBufferFromRemoteFS::writeCache(char * data, size_t size, size_t offset, FileSegment & file_segment)
699	{
700	    Stopwatch watch(CLOCK_MONOTONIC);
701	
702	    try
703	    {
704	        file_segment.write(data, size, offset);
705	    }
706	    catch (ErrnoException & e)
707	    {
708	        int code = e.getErrno();
709	        if (code == /* No space left on device */28 || code == /* Quota exceeded */122)
710	        {
711	            LOG_INFO(log, "Insert into cache is skipped due to insufficient disk space. ({})", e.displayText());
712	            return false;
713	        }
714	        throw;
715	    }
716	
717	    watch.stop();
718	    auto elapsed = watch.elapsedMicroseconds();
719	    current_file_segment_counters.increment(ProfileEvents::FileSegmentCacheWriteMicroseconds, elapsed);
720	    ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteMicroseconds, elapsed);
721	    ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteBytes, size);
722	
723	    return true;
724	}
